mapper.select:
SELECT FROM ( SELECT pay50.* , f_cdnm('ExpenseType' , pay50_expense_cd , pay50_company_id, pay50_reg_date) AS pay50_expense_nm , f_cdnm('TaxType' , pay50_tax_type , pay50_company_id, pay50_reg_date) AS pay50_tax_type_nm , f_cdnm('PayMethodCode' , pay50_pay_method_cd , pay50_company_id, pay50_reg_date) AS pay50_pay_method_nm , f_get_account_nm(pay50_company_id, pay50_account_cd) AS pay50_account_nm , ast1.ast01_class_tree_nm AS pay50_deposit_nm , ast2.ast01_class_tree_nm AS pay50_ast_nm , f_get_empTrans(pay50_reg_emp_id , pay50_reg_date, 'person_org_info') AS pay50_reg_emp_org_nm , f_get_empTrans(pay50_appr_emp_id , pay50_reg_date, 'person_org_info') AS pay50_appr_emp_org_nm , f_get_empTrans(pay50_confirmer_id , pay50_reg_date, 'person_org_info') AS pay50_confirmer_org_nm , f_get_empTrans(pay50_reg_emp_id , pay50_reg_date, 'org_code_nm') AS pay50_org_nm , COALESCE(sys15_corp_nm, f_emp_kor_nm(pay50_corp_id)) AS pay50_corp_nm , ( SELECT COUNT(*) FROM sys10_file WHERE sys10_parent_id = pay50_expense_id ) + ( SELECT COUNT(*) FROM com01_relate_appr WHERE com01_key_table_id = pay50_expense_id ) ||'건' AS pay50_file_count_str , CASE WHEN pay50_appr_emp_id IS NULL THEN '' ELSE (CASE WHEN COALESCE(apr1.apr01_status_cd,'99') = '30' THEN '완료' WHEN COALESCE(apr1.apr01_status_cd,'99') = '40' OR COALESCE(pay50_reject_reason,'') != '' THEN '반려' ELSE '진행중' END) END AS pay50_expense_status_nm , apr1.apr01_title AS pay50_expense_appr_title , apr1.apr01_status_cd AS pay50_expense_appr_status_cd , f_cdnm('AprStatusCode', apr1.apr01_status_cd, pay50_company_id, pay50_reg_date) AS pay50_expense_appr_status_nm FROM ( SELECT pay50_expense.* FROM pay50_expense WHERE pay50_company_id = #{companyId} AND pay50_confirm_status_cd IN ('20','80') /*(20:승인/80:PASS)*/ AND pay50_appr_emp_id IS NOT NULL AND pay50_occ_date BETWEEN #{startDate} AND #{closeDate} AND pay50_expense_cd LIKE #{expenseCode} ) pay50 LEFT OUTER JOIN sys15_corp ON sys15_corp_id = pay50_corp_id LEFT OUTER JOIN apr01_appr apr1 ON apr1.apr01_appr_id = pay50_expense_appr_id LEFT OUTER JOIN ast01_class_tree ast1 ON ast1.ast01_class_tree_id = pay50_deposit_id LEFT OUTER JOIN ast01_class_tree ast2 ON ast2.ast01_class_tree_id = pay50_ast_id WHERE 1=1
AND pay50_pay_method_cd LIKE #{payMethodCode}
AND COALESCE(pay50_reject_reason,'') = '' AND COALESCE(apr1.apr01_status_cd,'99') NOT IN ('30','40') /*(30:완료/40:반려)*/
AND pay50_appr_emp_id = #{personId} AND pay50_confirm_status_cd = '80'
AND 'Y' = CASE WHEN pay50_confirm_status_cd != '80' THEN 'Y' ELSE (CASE WHEN pay50_appr_emp_id != #{personId} AND COALESCE(apr1.apr01_status_cd,'99') = '99' THEN 'N' ELSE 'Y' END) END
) t WHERE CONCAT(pay50_expense_nm, pay50_desc, pay50_corp_nm, pay50_reg_emp_org_nm, pay50_note) ILIKE #{searchText} ORDER BY pay50_occ_date DESC, pay50_expense_id LIMIT #{limit}

SELECT apr01_status_cd
  FROM apr01_appr
 WHERE apr01_appr_id = #{apprId}

mapper.update:
UPDATE pay50_expense
   SET pay50_occ_date         = #{req.occDate}
     , pay50_desc             = #{req.desc}
     , pay50_corp_id          = #{req.corpId}
     , pay50_tax_type         = #{req.taxType}
     , pay50_amt              = #{req.amt}
     , pay50_tax              = #{req.tax}
     , pay50_settle_amt       = #{req.settleAmt}
     , pay50_due_date         = #{req.dueDate}
     , pay50_pay_method_cd    = #{req.payMethodCode}
     , pay50_pay_account_info = #{req.payAccountInfo}
     , pay50_account_cd       = #{req.accountCode}
     , pay50_note             = #{req.note}
     , pay50_deposit_id       = #{req.depositId}
     , pay50_ast_id           = #{req.astId}
 WHERE pay50_expense_id = #{expenseId}
   AND pay50_company_id = #{companyId}

UPDATE pay50_expense
   SET pay50_reject_reason = #{rejectReason}
     , pay50_reject_sms_yn = null
 WHERE pay50_expense_id  = #{expenseId}
   AND pay50_company_id  = #{companyId}

UPDATE pay50_expense
   SET pay50_appr_emp_id = #{apprEmpId}
 WHERE pay50_expense_id  = #{expenseId}
   AND pay50_company_id  = #{companyId}

UPDATE pay50_expense
   SET pay50_content    = #{content}
 WHERE pay50_expense_id = #{expenseId}
   AND pay50_company_id = #{companyId}

mapper.delete:
DELETE
  FROM pay50_expense
 WHERE pay50_expense_id  = #{expenseId}
   AND pay50_company_id  = #{companyId}
